#include <array>
#include <cstddef>
#include <iostream>
#include <span>
unsigned scalar(std::span<const unsigned> values) {
    unsigned sum = 0;
    for (unsigned value : values) sum += value;
    return sum;
}
unsigned paired(std::span<const unsigned> values) {
    unsigned sum = 0;
    std::size_t i = 0;
    for (; values.size() - i >= 2; i += 2) sum += values[i] + values[i + 1];
    if (i < values.size()) sum += values[i];
    return sum;
}
int main() {
    const std::array<unsigned, 5> values{2, 4, 6, 8, 10};
    std::cout << "scalar=" << scalar(values) << " paired=" << paired(values) << '\n';
}

#include <array>
#include <cstddef>
#include <iostream>
void show(const char* label, const std::array<int, 5>& a) {
    std::cout << label;
    for (int value : a) std::cout << ' ' << value;
    std::cout << '\n';
}
int main() {
    std::array<int, 5> forward{1, 2, 3, 4, 5};
    auto backward = forward;
    for (std::size_t i = 0; i < 4; ++i) forward[i + 1] = forward[i];
    for (std::size_t i = 4; i > 0; --i) backward[i] = backward[i - 1];
    show("forward:", forward);
    show("backward:", backward);
}
